{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":1590,"end":1677,"raw_source":""active catalog metadata qualifies matching Pi models without changing local fallbacks"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""active catalog metadata qualifies matching Pi models without changing local fallbacks"","registration_line":36,"start":1585,"end":3907,"registration_guards":[]},"title_hierarchy":[{"registration_line":36,"call":"test","title_source":""active catalog metadata qualifies matching Pi models without changing local fallbacks""}],"guards":[],"non_ascii_source":false,"call_source":"test("active catalog metadata qualifies matching Pi models without changing local fallbacks", () => {
	const catalog = parseAndValidateModelCatalog(
		readFileSync(join(import.meta.dirname, "..", "catalog", "fixtures", "account-snapshot-v1.json"), "utf8"),
		{ remote: true },
	);
	const matching = catalogPickerModel(
		{
			provider: "ai.example.gateway",
			id: "example-model",
			name: "Pi label",
			contextWindow: 1,
			maxTokens: 1,
		},
		catalog,
	);
	assert.deepEqual(
		{
			catalogId: matching.catalogId,
			offeringId: matching.offeringId,
			name: matching.name,
			contextWindow: matching.contextWindow,
			maxTokens: matching.maxTokens,
			available: matching.available,
		},
		{
			catalogId: "ai.example.test",
			offeringId: "ai.example.gateway/example-model",
			name: "Example Model",
			contextWindow: 131072,
			maxTokens: 32768,
			available: true,
		},
	);
	assert.deepEqual(catalogModelReference("ai.example.gateway", "example-model", catalog), {
		catalogId: "ai.example.test",
		offeringId: "ai.example.gateway/example-model",
		provider: "ai.example.gateway",
		modelId: "example-model",
	});
	assert.deepEqual(catalogModelReference("local", "unlisted", catalog), {
		provider: "local",
		modelId: "unlisted",
	});

	const secondCatalog = structuredClone(catalog);
	secondCatalog.catalogId = "org.example.second";
	secondCatalog.modelOfferings[0].id = "org.example.second/example-model";
	secondCatalog.modelOfferings[0].name = "Second route";
	const qualified = catalogPickerModels(
		{
			provider: "ai.example.gateway",
			id: "example-model",
			name: "Pi label",
			contextWindow: 1,
			maxTokens: 1,
		},
		[
			{
				source: {
					id: "first",
					label: "First catalog",
					url: "https://first.test/catalog",
					enabled: true,
					auth: { type: "none" },
				},
				document: catalog,
			},
			{
				source: {
					id: "second",
					label: "Second catalog",
					url: "https://second.test/catalog",
					enabled: true,
					auth: { type: "none" },
				},
				document: secondCatalog,
			},
		],
	);
	assert.deepEqual(
		qualified.map((model) => [model.catalogId, model.offeringId, model.catalogLabel]),
		[
			["ai.example.test", "ai.example.gateway/example-model", "First catalog"],
			["org.example.second", "org.example.second/example-model", "Second catalog"],
		],
	);
})","selector_identity":{"source_title":""active catalog metadata qualifies matching Pi models without changing local fallbacks"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

