{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":3915,"end":3994,"raw_source":""catalog offering ratings populate picker comparisons without importing prices"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""catalog offering ratings populate picker comparisons without importing prices"","registration_line":124,"start":3910,"end":5139,"registration_guards":[]},"title_hierarchy":[{"registration_line":124,"call":"test","title_source":""catalog offering ratings populate picker comparisons without importing prices""}],"guards":[],"non_ascii_source":false,"call_source":"test("catalog offering ratings populate picker comparisons without importing prices", () => {
	const document = JSON.parse(
		readFileSync(join(import.meta.dirname, "..", "catalog", "fixtures", "account-snapshot-v1.json"), "utf8"),
	);
	const model = {
		provider: "ai.example.gateway",
		id: "example-model",
		name: "Pi label",
		contextWindow: 1,
		maxTokens: 1,
	};
	for (const tier of [1, 2, 3, 4]) {
		document.modelOfferings[0].metadata = {
			strength: tier,
			speed: tier,
			cost: tier,
			price: { currency: "USD", input: 99, output: 199, unit: "per_1m_tokens" },
			other: "ignored",
		};
		const catalog = parseAndValidateModelCatalog(JSON.stringify(document), { remote: true });
		const snapshot = structuredClone(catalog);
		const pickerModel = catalogPickerModel(model, catalog);
		assert.deepEqual(pickerModel.comparison, { strength: tier, speed: tier, cost: tier });
		assert.equal(pickerModel.price, undefined);
		assert.equal(pickerModel.cost, undefined);
		assert.deepEqual(catalog, snapshot, "reading ratings does not mutate the catalog");
	}
	assert.equal(catalogPickerModel(model).comparison, undefined);
