{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":8016,"end":8075,"raw_source":""catalog offering lookups index an immutable snapshot once"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""catalog offering lookups index an immutable snapshot once"","registration_line":230,"start":8011,"end":9182,"registration_guards":[]},"title_hierarchy":[{"registration_line":230,"call":"test","title_source":""catalog offering lookups index an immutable snapshot once""}],"guards":[],"non_ascii_source":false,"call_source":"test("catalog offering lookups index an immutable snapshot once", () => {
	const catalog = parseAndValidateModelCatalog(
		readFileSync(join(import.meta.dirname, "..", "catalog", "fixtures", "account-snapshot-v1.json"), "utf8"),
		{ remote: true },
	);
	let offeringReads = 0;
	catalog.modelOfferings = new Proxy(catalog.modelOfferings, {
		get(target, property, receiver) {
			if (typeof property === "string" && /^\d+$/u.test(property)) offeringReads += 1;
			return Reflect.get(target, property, receiver);
		},
	});
	const activeCatalogs = [
		{
			source: {
				id: "indexed",
				label: "Indexed catalog",
				url: "https://indexed.test/catalog",
				enabled: true,
				auth: { type: "none" },
			},
			document: catalog,
		},
	];
	const model = {
		provider: "ai.example.gateway",
		id: "example-model",
		name: "Pi label",
		contextWindow: 1,
		maxTokens: 1,
	};

	assert.equal(catalogPickerModels(model, activeCatalogs)[0].name, "Example Model");
	const readsAfterIndexing = offeringReads;
	assert.ok(readsAfterIndexing > 0);
	assert.equal(catalogPickerModels(model, activeCatalogs)[0].name, "Example Model");
	assert.equal(offeringReads, readsAfterIndexing);
