{"kind":"protected-fixture-schema-value","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":17865,"end":17873,"raw_source":""\x1b[F"","token_kind":"string","call_name":"test","argument_index":1,"test_owner":{"title_source":""Models fills the shared height budget, pages visibly, and survives short-terminal resizing"","registration_line":500,"start":16620,"end":18391,"registration_guards":[]},"title_hierarchy":[{"registration_line":500,"call":"test","title_source":""Models fills the shared height budget, pages visibly, and survives short-terminal resizing""}],"guards":[{"kind":"for","line":505,"start":16907,"end":16935,"raw":"const locale of ["en", "ja"]","polarity":"for-body"}],"non_ascii_source":false,"call_source":"test("Models fills the shared height budget, pages visibly, and survives short-terminal resizing", () => {
	const inventory = Array.from({ length: 100 }, (_, index) => ({
		...rows()[1],
		model: { ...rows()[1].model, modelId: `model-${index}`, name: `Model ${index} 日本語` },
	}));
	for (const locale of ["en", "ja"]) {
		const terminal = { rows: 80 };
		const { component } = createComponent({
			terminal,
			catalog: resolveCatalog(locale).bundle,
			getRows: () => inventory,
			keybindings: fakeKeybindings({ "tui.select.confirm": ["ctrl+shift+enter"] }),
		});
		for (const width of [24, 48, 80, 120]) {
			const lines = component.render(width);
			assert.equal(lines.length, paletteHeightBudget(terminal.rows));
			assert.ok(lines.every((line) => visibleWidth(line) <= width));
			assert.ok(lines.filter((line) => line.includes("Model ")).length > 12);
			assert.match(stripSgr(lines.join("\n")), /Ctrl\+Shift\+Enter/u);
			assert.match(lines.join("\n"), /Esc\/Ctrl\+C/u);
		}
		const pageSize = component.render(120).filter((line) => line.includes("Model ")).length;
		component.handleInput("pageDown");
		assert.match(stripSgr(component.render(120).join("\n")), new RegExp(`→.*Model ${pageSize}(?:\\s|$)`, "u"));
		component.handleInput("\x1b[F");
		for (const rows of [24, 16, 12, 8, 4, 1, 80]) {
			terminal.rows = rows;
			for (const width of [24, 48, 80, 120]) {
				const lines = component.render(width);
				assert.ok(lines.length <= paletteHeightBudget(rows));
				assert.ok(lines.every((line) => visibleWidth(line) <= width));
				if (rows >= 12) {
					assert.match(stripSgr(lines.join("\n")), /→.*Model 99/u);
					assert.match(lines.join("\n"), /Esc\/Ctrl\+C/u);
					assert.ok(lines.at(-1).startsWith("╰"));
				}
			}
		}
		component.dispose();
	}
})"}

{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":18399,"end":18472,"raw_source":""Models scrolls a bounded viewport and marks hidden rows above and below"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models scrolls a bounded viewport and marks hidden rows above and below"","registration_line":542,"start":18394,"end":20402,"registration_guards":[]},"title_hierarchy":[{"registration_line":542,"call":"test","title_source":""Models scrolls a bounded viewport and marks hidden rows above and below""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models scrolls a bounded viewport and marks hidden rows above and below", () => {
	const inventory = Array.from({ length: 100 }, (_, index) => ({
		...rows()[1],
		model: { ...rows()[1].model, modelId: `model-${index}`, name: `Model ${index}` },
	}));
	const terminal = { rows: 24 };
	const { component } = createComponent({ terminal, getRows: () => inventory });
	const render = () => stripSgr(component.render(80).join("\n"));
	const tall = render();
	assert.match(tall, /→.*Model 0/u);
	assert.match(tall, /█/u, "the scrollbar thumb marks the current position");
	assert.match(tall, /▼/u, "the scrollbar marks content below the viewport");
	assert.doesNotMatch(tall, /▲/u);

	terminal.rows = 12;
	let view = render();
	assert.match(view, /→.*Model 0/u);
	assert.match(view, /▼/u);
	assert.doesNotMatch(view, /▲/u);

	component.handleInput("down");
	view = render();
	assert.match(view, /→.*Model 1/u);
	assert.match(view, /↕/u);
	component.handleInput("up");
	view = render();
	assert.match(view, /→.*Model 0/u);
	assert.match(view, /▼/u);

	component.handleInput("pageDown");
	view = render();
	assert.match(view, /→.*Model 1/u);
	assert.match(view, /↕/u, "one visible row reports both hidden sides");
	component.handleInput("pageUp");
	view = render();
	assert.match(view, /→.*Model 0/u);
	assert.match(view, /▼/u);

	component.handleInput("\x1b[F");
	view = render();
	assert.match(view, /→.*Model 99/u);
	assert.match(view, /▲/u);
	assert.doesNotMatch(view, /▼/u);

	component.handleInput("\x1b[H");
	view = render();
	assert.match(view, /→.*Model 0/u);
	assert.match(view, /▼/u);

	component.handleInput("/");
	component.handleInput("\x1b[1;5F");
	view = render();
	assert.match(view, /→.*Model 99/u, "Ctrl+End reaches the last item while search holds focus");
	assert.match(view, /▲/u);
	component.handleInput("\x1b[1;5H");
	view = render();
	assert.match(view, /→.*Model 0/u, "Ctrl+Home returns to the first item while search holds focus");
	assert.match(view, /▼/u);
	component.dispose();
})","selector_identity":{"source_title":""Models scrolls a bounded viewport and marks hidden rows above and below"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

