{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":20410,"end":20494,"raw_source":""Models reserves wrapped messages and full action hints before allocating list rows"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models reserves wrapped messages and full action hints before allocating list rows"","registration_line":603,"start":20405,"end":21211,"registration_guards":[]},"title_hierarchy":[{"registration_line":603,"call":"test","title_source":""Models reserves wrapped messages and full action hints before allocating list rows""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models reserves wrapped messages and full action hints before allocating list rows", () => {
	const terminal = { rows: 24 };
	const { component } = createComponent({ terminal });
	component.handleInput("enter");
	for (const width of [24, 48, 80, 120]) {
		const lines = component.render(width);
		assert.ok(lines.length <= paletteHeightBudget(terminal.rows));
		assert.ok(lines.every((line) => visibleWidth(line) <= width));
		assert.match(lines.join("\n"), /→/u);
		if (width >= 48) assert.match(lines.join("\n"), /→.*Tiny/u);
		assert.match(lines.join("\n"), /Esc\/Ctrl\+C cancel/u);
		const text = lines.join("").replaceAll(/[│\s]/gu, "");
		assert.ok(text.includes("Entercompactandswitch"));
		assert.ok(text.includes("Compacttheactivecontextandswitchtosmall/tiny?"));
	}
	component.dispose();
