{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":21219,"end":21292,"raw_source":""Models scrolls through every line of a long message in a short terminal"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models scrolls through every line of a long message in a short terminal"","registration_line":621,"start":21214,"end":22656,"registration_guards":[]},"title_hierarchy":[{"registration_line":621,"call":"test","title_source":""Models scrolls through every line of a long message in a short terminal""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models scrolls through every line of a long message in a short terminal", async () => {
	const terminal = { rows: 16 };
	const { component } = createComponent({
		terminal,
		getRows: () => [{ ...rows()[1], contextFit: "fits", model: { ...rows()[1].model, name: "Tiny" } }],
		onRefresh: async () => {
			throw new Error("network unreachable while reading the Office pool catalog; retry with /reload");
		},
	});
	await new Promise((resolve) => setImmediate(resolve));
	for (const width of [24, 48, 80, 120]) {
		const lines = component.render(width);
		assert.ok(lines.length <= paletteHeightBudget(terminal.rows));
		assert.ok(lines.every((line) => visibleWidth(line) <= width));
		assert.match(lines.join("\n"), /→.*Tiny/u);
		assert.match(lines.join("\n"), /Esc\/Ctrl\+C close/u);
		const seen = [...lines];
		if (!lines.join("\n").includes("/reload")) {
			for (let page = 0; page < 20; page += 1) {
				component.handleInput("pageDown");
				seen.push(...component.render(width));
			}
		}
		const text = stripSgr(seen.join(" ")).replaceAll(/\s+/gu, " ");
		assert.match(text, /Model refresh/u);
