{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":29623,"end":29677,"raw_source":""Models view hints render effective semantic bindings"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models view hints render effective semantic bindings"","registration_line":846,"start":29618,"end":30218,"registration_guards":[]},"title_hierarchy":[{"registration_line":846,"call":"test","title_source":""Models view hints render effective semantic bindings""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models view hints render effective semantic bindings", () => {
