{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":31512,"end":31572,"raw_source":""Models view refreshes catalogs through the refresh binding"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models view refreshes catalogs through the refresh binding"","registration_line":903,"start":31507,"end":32326,"registration_guards":[]},"title_hierarchy":[{"registration_line":903,"call":"test","title_source":""Models view refreshes catalogs through the refresh binding""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models view refreshes catalogs through the refresh binding", () => {
	const refreshSignals = [];
	const { component, calls } = createComponent({
		onRefreshCatalogs: (signal) => {
			refreshSignals.push(signal);
			return new Promise((_resolve, reject) => {
				signal.addEventListener("abort", () => reject(new Error("aborted")));
			});
		},
