{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":32334,"end":32402,"raw_source":""Models view recomputes rows when catalogs reload in the background"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models view recomputes rows when catalogs reload in the background"","registration_line":923,"start":32329,"end":33080,"registration_guards":[]},"title_hierarchy":[{"registration_line":923,"call":"test","title_source":""Models view recomputes rows when catalogs reload in the background""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models view recomputes rows when catalogs reload in the background", () => {
	const listeners = new Set();
	let rowCount = 0;
	const { component, calls } = createComponent({
		getRows: () => {
			rowCount += 1;
			return rows();
		},
		subscribeCatalogsReloaded: (listener) => {
			listeners.add(listener);
			return () => {
				listeners.delete(listener);
			};
		},
	});
	const computedBefore = rowCount;
	const rendersBefore = calls.renders;
	for (const listener of listeners) listener();
	assert.ok(rowCount > computedBefore, "rows are recomputed after the reload");
	assert.ok(calls.renders > rendersBefore, "the view re-renders after the reload");
	component.dispose();
	assert.equal(listeners.size, 0, "dispose unsubscribes the view");
})","selector_identity":{"source_title":""Models view recomputes rows when catalogs reload in the background"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

