{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":33927,"end":33999,"raw_source":""Models shows comparison columns as unknown without assessment evidence"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models shows comparison columns as unknown without assessment evidence"","registration_line":967,"start":33922,"end":34742,"registration_guards":[]},"title_hierarchy":[{"registration_line":967,"call":"test","title_source":""Models shows comparison columns as unknown without assessment evidence""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models shows comparison columns as unknown without assessment evidence", () => {
	for (const [locale, headers] of [
		["en", /Strength\s+Speed\s+Cost/u],
		["ja", /実力\s+速度\s+コスト/u],
		["zh-Hans", /Strength\s+Speed\s+Cost/u],
		["zh-Hant", /Strength\s+Speed\s+Cost/u],
	]) {
		const { component } = createComponent({ catalog: resolveCatalog(locale).bundle });
		const wide = stripSgr(component.render(120).join("\n"));
		assert.match(wide, headers, locale);
		assert.match(wide, /→.*Tiny.*—\s+—\s+—/u, locale);
		for (const width of [24, 48, 72, 80, 96, 120]) {
			assert.ok(
				component.render(width).every((line) => visibleWidth(line) <= width),
				`${locale}: ${width}`,
			);
		}
		const narrow = stripSgr(component.render(48).join("\n"));
		assert.doesNotMatch(narrow, headers);
		component.dispose();
	}
})","selector_identity":{"source_title":""Models shows comparison columns as unknown without assessment evidence"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

