{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":34750,"end":34828,"raw_source":""Models renders catalog ratings with localized headers within terminal widths"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models renders catalog ratings with localized headers within terminal widths"","registration_line":990,"start":34745,"end":35925,"registration_guards":[]},"title_hierarchy":[{"registration_line":990,"call":"test","title_source":""Models renders catalog ratings with localized headers within terminal widths""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models renders catalog ratings with localized headers within terminal widths", () => {
	const document = JSON.parse(
		readFileSync(join(import.meta.dirname, "..", "catalog", "fixtures", "account-snapshot-v1.json"), "utf8"),
	);
	document.modelOfferings[0].name = "評価 Model";
	document.modelOfferings[0].metadata = { strength: 4, speed: 3, cost: 2 };
	const catalog = parseAndValidateModelCatalog(JSON.stringify(document), { remote: true });
	const model = catalogPickerModel(
		{ provider: "ai.example.gateway", id: "example-model", name: "Pi label", contextWindow: 1, maxTokens: 1 },
		catalog,
	);
	for (const locale of ["en", "ja"]) {
		const { component } = createComponent({
			catalog: resolveCatalog(locale).bundle,
			getRows: () => [{ ...rows()[1], model }],
		});
		const wide = stripSgr(component.render(120).join("\n"));
		assert.match(wide, /評価 Model.*★★★★\s+↯↯↯\s+\$\$/u);
		for (const width of [24, 48, 72, 80, 96, 120]) {
			assert.ok(
				component.render(width).every((line) => visibleWidth(line) <= width),
				`${locale}: ${width}`,
			);
		}
		assert.doesNotMatch(stripSgr(component.render(48).join("\n")), /★★★★|↯|\$\$/u);
		component.dispose();
	}
})","selector_identity":{"source_title":""Models renders catalog ratings with localized headers within terminal widths"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

