{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":35933,"end":36006,"raw_source":""Models renders one to four comparison symbols and rejects invalid tiers"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models renders one to four comparison symbols and rejects invalid tiers"","registration_line":1019,"start":35928,"end":37277,"registration_guards":[]},"title_hierarchy":[{"registration_line":1019,"call":"test","title_source":""Models renders one to four comparison symbols and rejects invalid tiers""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models renders one to four comparison symbols and rejects invalid tiers", () => {
	const inventory = [1, 2, 3, 4, 0, 5, 1.5].map((tier) => ({
		...rows()[1],
		model: { ...rows()[1].model, name: `Tier ${tier}`, comparison: { strength: tier, speed: tier, cost: tier } },
	}));
	const { component } = createComponent({ getRows: () => inventory });
	const lines = component.render(120).map(stripSgr);
	const header = lines.find((line) => /Strength\s+Speed\s+Cost/u.test(line));
	assert.ok(header);
	for (const tier of [1, 2, 3, 4]) {
		const line = lines.find((value) => value.includes(`Tier ${tier} `));
		assert.ok(line, `tier ${tier}`);
		for (const [label, symbol] of [
			["Strength", "★"],
			["Speed", "↯"],
			["Cost", "$"],
		]) {
			assert.ok(line.includes(symbol.repeat(tier)), `${label}: tier ${tier}`);
			assert.equal(
				visibleWidth(line.slice(0, line.indexOf(symbol))),
				visibleWidth(header.slice(0, header.indexOf(label))),
				`${label}: tier ${tier} aligns with its header`,
			);
		}
	}
	for (const tier of [0, 5, 1.5]) {
		const line = lines.find((value) => value.includes(`Tier ${tier} `));
		assert.match(line, /—\s+—\s+—/u);
	}
	for (const width of [24, 48, 72, 80, 96, 120]) {
		assert.ok(
			component.render(width).every((line) => visibleWidth(line) <= width),
			`width ${width}`,
		);
	}
	component.dispose();
})","selector_identity":{"source_title":""Models renders one to four comparison symbols and rejects invalid tiers"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

