{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":37285,"end":37362,"raw_source":""Models rating rows align under an independent single-cell text cursor model"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models rating rows align under an independent single-cell text cursor model"","registration_line":1057,"start":37280,"end":38846,"registration_guards":[]},"title_hierarchy":[{"registration_line":1057,"call":"test","title_source":""Models rating rows align under an independent single-cell text cursor model""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models rating rows align under an independent single-cell text cursor model", () => {
	const inventory = [undefined, 1, 2, 3, 4].map((tier) => ({
		...rows()[1],
		model: {
			...rows()[1].model,
			name: `Cells ${tier ?? "unknown"}`,
			comparison: tier === undefined ? undefined : { strength: 4, speed: tier, cost: 2 },
		},
	}));
	// This fixture contains only ASCII and single-cell text glyphs. Model a terminal
	// honoring VS15 as zero-width without consulting Pi's width implementation.
	const cursorColumns = (value) => {
		const text = value.replace(/\uFE0E/gu, "");
		assert.match(text, /^[\x20-\x7e│→★↯—⚡]*$/u);
		return Array.from(text).length;
	};
	const { component } = createComponent({ getRows: () => inventory });
	for (const width of [48, 72, 80, 96, 120, 160]) {
		const lines = component.render(width).map(stripSgr);
		const header = lines.find((line) => /Strength\s+Speed\s+Cost/u.test(line));
		for (const tier of [undefined, 1, 2, 3, 4]) {
			const line = lines.find((line) => line.includes(`Cells ${tier ?? "unknown"} `));
			assert.ok(line, `width ${width}, tier ${tier}`);
			assert.equal(cursorColumns(line), width, `width ${width}, tier ${tier}: right border`);
			assert.doesNotMatch(line, /[\uFE0E\uFE0F]|\p{Emoji_Presentation}/u, "ratings use plain text glyphs");
			if (header && tier !== undefined) {
				assert.equal(
					cursorColumns(line.slice(0, line.indexOf("$"))),
					cursorColumns(header.slice(0, header.indexOf("Cost"))),
					`width ${width}, tier ${tier}: Cost column`,
				);
			}
		}
	}
	component.dispose();
})","selector_identity":{"source_title":""Models rating rows align under an independent single-cell text cursor model"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

