{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":38854,"end":38938,"raw_source":""Models columns name the catalog for shared identities and drop on narrow terminals"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models columns name the catalog for shared identities and drop on narrow terminals"","registration_line":1094,"start":38849,"end":40037,"registration_guards":[]},"title_hierarchy":[{"registration_line":1094,"call":"test","title_source":""Models columns name the catalog for shared identities and drop on narrow terminals""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models columns name the catalog for shared identities and drop on narrow terminals", () => {
	const shared = (catalogLabel, rank) => ({
		section: "other",
		model: {
			provider: "shisa",
			providerName: "Shisa AI",
			modelId: "shisa-v2.1-70b",
			name: "Shisa V2.1 70B",
			catalogLabel,
			contextWindow: 65_536,
			available: true,
		},
		contextFit: "fits",
		favorite: rank === 0,
		projectDefault: false,
		rank,
	});
	const { component } = createComponent({ getRows: () => [shared("Shisa API", 0), shared("codex-pool", 1)] });
	const wide = stripSgr(component.render(96).join("\n"));
	assert.match(wide, /→ {2}★ {2}Shisa V2\.1 70B\s+Shisa AI · Shisa API\s+65\.5K/u);
	assert.match(wide, /Shisa V2\.1 70B\s+Shisa AI · codex-pool\s+65\.5K/u);
	assert.match(wide, /shisa\/shisa-v2\.1-70b · Shisa API · context 65\.5K/u);
	for (const width of [24, 48, 96]) {
		assert.ok(
			component.render(width).every((line) => visibleWidth(line) === width),
			`width ${width}`,
		);
	}
	const narrow = stripSgr(component.render(36).join("\n"));
	assert.doesNotMatch(narrow, /Provider|Context/u, "narrow terminals keep only the name column");
	assert.match(narrow, /Shisa V2\.1 70B/u);
})","selector_identity":{"source_title":""Models columns name the catalog for shared identities and drop on narrow terminals"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

