{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":44084,"end":44159,"raw_source":""Models view returns to the pre-search position when the search is cleared"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""Models view returns to the pre-search position when the search is cleared"","registration_line":1214,"start":44079,"end":45915,"registration_guards":[]},"title_hierarchy":[{"registration_line":1214,"call":"test","title_source":""Models view returns to the pre-search position when the search is cleared""}],"guards":[],"non_ascii_source":false,"call_source":"test("Models view returns to the pre-search position when the search is cleared", () => {
	const inventory = Array.from({ length: 40 }, (_, index) => ({
		section: "other",
		model: {
			provider: "p",
			modelId: `m${String(index).padStart(2, "0")}`,
			name: `Model ${index}`,
			contextWindow: 200_000,
			maxTokens: 10_000,
			available: true,
		},
		contextFit: "fits",
		favorite: false,
		projectDefault: false,
		rank: index,
	}));
	const { component, calls } = createComponent({
		getRows: (query) => (query ? inventory.filter((row) => row.model.modelId.includes(query.trim())) : inventory),
	});
	const selectedId = () => /\bp\/(m\d+)/u.exec(stripSgr(component.render(96).join("\n")))?.[1];
	for (let step = 0; step < 5; step += 1) component.handleInput("down");
	assert.equal(selectedId(), "m05");

	component.handleInput("3");
	assert.equal(selectedId(), "m03", "editing the query selects the first matching row");
	component.handleInput("escape");
	assert.equal(calls.close, 0);
	assert.equal(selectedId(), "m05", "the first Esc clears the search and returns to the pre-search position");
	assert.match(stripSgr(component.render(96).join("\n")), /Esc\/Ctrl\+C close/u);

	component.handleInput("3");
	component.handleInput("down");
	assert.equal(selectedId(), "m13", "moving through results keeps the query");
	assert.doesNotMatch(component.render(96).join("\n"), /→ Search/u, "moving through results leaves the search field");
	assert.match(stripSgr(component.render(96).join("\n")), /Esc\/Ctrl\+C clear search/u);
	component.handleInput("escape");
	assert.equal(selectedId(), "m05", "Esc from the results also clears the search and restores the position");

	component.handleInput("3");
	component.handleInput("\u007f");
	assert.equal(selectedId(), "m05", "deleting the query also returns to the pre-search position");
})","selector_identity":{"source_title":""Models view returns to the pre-search position when the search is cleared"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

