{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":56933,"end":57034,"raw_source":""favorite cycling handles empty, active, unauthenticated, and failed switches without stock fallback"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""favorite cycling handles empty, active, unauthenticated, and failed switches without stock fallback"","registration_line":1541,"start":56928,"end":59289,"registration_guards":[]},"title_hierarchy":[{"registration_line":1541,"call":"test","title_source":""favorite cycling handles empty, active, unauthenticated, and failed switches without stock fallback""}],"guards":[],"non_ascii_source":false,"call_source":"test("favorite cycling handles empty, active, unauthenticated, and failed switches without stock fallback", async (t) => {
	await t.test("empty favorite list", async () => {
		const harness = await createFavoriteCycleHarness();
		try {
			assert.equal(await harness.integration.cycleFavorite("forward"), true);
			assert.deepEqual(harness.selected, []);
			assert.match(harness.notifications[0][0], /No favorite models/);
		} finally {
			await harness.dispose();
		}
	});
	await t.test("active model call", async () => {
		const harness = await createFavoriteCycleHarness({ favorites: ["a", "b", "c"], isIdle: false });
		try {
			assert.equal(await harness.integration.cycleFavorite("forward"), true);
			assert.equal(await harness.integration.cycleFavorite("forward"), true);
			assert.equal(await harness.integration.cycleFavorite("forward"), true);
			assert.deepEqual(harness.selected, []);
			assert.deepEqual(
				harness.notifications.map(([message]) => message.match(/p\/[abc]/)?.[0]),
				["p/b", "p/c", "p/a"],
			);
			await harness.handlers.get("turn_end")({}, harness.ctx);
			assert.deepEqual(harness.selected, ["a"]);
			assert.match(harness.notifications.at(-1)[0], /Switched to p\/a/);
			// Cycling switches models without ever persisting a project default.
			assert.deepEqual(new ModelPickerStore(harness.paths).load().state.defaults.projects, {});
		} finally {
			await harness.dispose();
		}
	});
	await t.test("missing authentication", async () => {
		const harness = await createFavoriteCycleHarness({ favorites: ["a", "b"], setModel: async () => false });
		try {
			assert.equal(await harness.integration.cycleFavorite("forward"), true);
			assert.deepEqual(harness.selected, ["b"]);
			assert.match(harness.notifications[0][0], /No authentication for p\/b/);
		} finally {
			await harness.dispose();
		}
	});
	await t.test("activation error", async () => {
		const harness = await createFavoriteCycleHarness({
			favorites: ["a", "b"],
			setModel: async () => {
				throw new Error("broken\u001b]0;hidden\u0007 provider");
			},
		});
		try {
			assert.equal(await harness.integration.cycleFavorite("forward"), true);
			assert.match(harness.notifications[0][0], /Favorite model switch failed: broken provider/);
			assert.doesNotMatch(harness.notifications[0][0], /hidden/);
		} finally {
			await harness.dispose();
		}
	});
})","selector_identity":{"source_title":""favorite cycling handles empty, active, unauthenticated, and failed switches without stock fallback"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

