{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":60628,"end":60694,"raw_source":""/about routes to Settings About and reports text outside the TUI"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""/about routes to Settings About and reports text outside the TUI"","registration_line":1637,"start":60623,"end":62211,"registration_guards":[]},"title_hierarchy":[{"registration_line":1637,"call":"test","title_source":""/about routes to Settings About and reports text outside the TUI""}],"guards":[],"non_ascii_source":false,"call_source":"test("/about routes to Settings About and reports text outside the TUI", async (t) => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-about-command-"));
	t.after(() => rmSync(root, { recursive: true, force: true }));
	const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
	const commands = new Map();
	const handlers = new Map();
	const integration = createJouzuModelPicker(paths, {
		palette: { env: {}, columns: 100, rows: 30 },
		runtime: { about: () => "Running Jouzu startup-build\nPi test-pi" },
	});
	integration.extension.factory({
		on: (name, handler) => handlers.set(name, handler),
		registerCommand: (name, command) => commands.set(name, command),
		setModel: async () => true,
	});
	const rendered = [];
	const notices = [];
	const ctx = {
		mode: "tui",
		ui: {
			notify: (text) => notices.push(text),
			custom: (factory) =>
				new Promise((resolve) => {
					const component = factory(
						{ terminal: { rows: 30 }, requestRender() {} },
						identityTheme,
						fakeKeybindings(),
						resolve,
					);
					setImmediate(() => {
						rendered.push(component.render(80).join("\n"));
						component.handleInput("escape");
					});
				}),
		},
	};
	await commands.get("about").handler("", ctx);
	assert.match(rendered[0], /Settings/);
	assert.match(rendered[0], /About/);
	assert.match(rendered[0], /startup-build/);
	await commands.get("about").handler("", { ...ctx, mode: "rpc" });
	assert.deepEqual(notices, ["Running Jouzu startup-build\nPi test-pi"]);
	assert.equal(rendered.length, 1);
	await handlers.get("session_shutdown")({}, ctx);
})","selector_identity":{"source_title":""/about routes to Settings About and reports text outside the TUI"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

