{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":71658,"end":71716,"raw_source":""context-small selection compacts before switching models"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""context-small selection compacts before switching models"","registration_line":1975,"start":71653,"end":74017,"registration_guards":[]},"title_hierarchy":[{"registration_line":1975,"call":"test","title_source":""context-small selection compacts before switching models""}],"guards":[],"non_ascii_source":false,"call_source":"test("context-small selection compacts before switching models", async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-model-picker-compact-switch-"));
	try {
		const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
		const integration = createJouzuModelPicker(paths);
		const handlers = new Map();
		const selected = [];
		let ctx;
		integration.extension.factory({
			on(name, handler) {
				handlers.set(name, handler);
			},
			async setModel(model) {
				selected.push(model.id);
				ctx.model = model;
				return true;
			},
		});
		const models = [
			{ provider: "p", id: "large", name: "Large", contextWindow: 100_000, maxTokens: 16_000 },
			{ provider: "p", id: "small", name: "Small", contextWindow: 8_000, maxTokens: 8_000 },
		];
		let contextTokens = 10_000;
		let compactOptions;
		ctx = {
			mode: "tui",
			cwd: root,
			model: models[0],
			scopedModels: [],
			sessionManager: { getBranch: () => [] },
			modelRegistry: {
				getAvailable: () => models,
				find: (provider, id) => (provider === "p" ? models.find((model) => model.id === id) : undefined),
				refresh: async () => ({ errors: new Map() }),
			},
			getContextUsage: () => ({ tokens: contextTokens, contextWindow: 100_000, percent: 10 }),
			isIdle: () => true,
			compact(options) {
				compactOptions = options;
				setImmediate(() => {
					contextTokens = 1_000;
					options.onComplete({ summary: "brief", firstKeptEntryId: "", tokensBefore: 10_000 });
				});
			},
			ui: {
				notify() {},
				custom(factory) {
					return new Promise((resolve) => {
						const component = factory(
							{ terminal: { rows: 30 }, requestRender() {} },
							identityTheme,
							fakeKeybindings(),
							resolve,
						);
						setImmediate(() => {
							component.handleInput("down");
							component.handleInput("enter");
							component.handleInput("enter");
						});
					});
				},
			},
		};
		await handlers.get("session_start")({ reason: "startup" }, ctx);
		assert.equal(await integration.open({ source: "action" }), true);
		assert.equal(compactOptions.customInstructions, "keep:0");
		assert.deepEqual(selected, ["small"]);
		assert.deepEqual(new ModelPickerStore(paths).load().state.defaults.projects[deriveProjectKey(root)], {
			provider: "p",
			modelId: "small",
		});
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})","selector_identity":{"source_title":""context-small selection compacts before switching models"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

