{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":74025,"end":74116,"raw_source":""new sessions apply an available project default through session-only extension activation"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""new sessions apply an available project default through session-only extension activation"","registration_line":2051,"start":74020,"end":75982,"registration_guards":[]},"title_hierarchy":[{"registration_line":2051,"call":"test","title_source":""new sessions apply an available project default through session-only extension activation""}],"guards":[],"non_ascii_source":false,"call_source":"test("new sessions apply an available project default through session-only extension activation", async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-model-picker-default-"));
	try {
		const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
		const projectKey = deriveProjectKey(root);
		new ModelPickerStore(paths).setProjectDefault({ provider: "p", modelId: "b" }, projectKey);
		const integration = createJouzuModelPicker(paths, { applyProjectDefaultAtStartup: true });
		const handlers = new Map();
		const selected = [];
		integration.extension.factory({
			on(name, handler) {
				handlers.set(name, handler);
			},
			async setModel(model) {
				selected.push(model.id);
				return true;
			},
		});
		const current = { provider: "p", id: "a", name: "A", contextWindow: 100_000, maxTokens: 10_000 };
		const target = { provider: "p", id: "b", name: "B", contextWindow: 100_000, maxTokens: 10_000 };
		let branch = [
			{ type: "model_change", provider: "p", modelId: "a" },
			{ type: "thinking_level_change", thinkingLevel: "off" },
		];
		const ctx = {
			mode: "tui",
			cwd: root,
			model: current,
			scopedModels: [],
			sessionManager: { getBranch: () => branch },
			modelRegistry: { find: () => target },
			ui: { notify() {} },
		};
		await handlers.get("session_start")({ reason: "startup" }, ctx);
		assert.deepEqual(selected, ["b"]);

		branch = [...branch, { type: "message", message: { role: "user", content: "existing" } }];
		await handlers.get("session_start")({ reason: "new" }, ctx);
		assert.deepEqual(selected, ["b"], "a session with conversation messages must keep its restored model");

		branch = branch.filter((entry) => entry.type !== "message");
		ctx.scopedModels = [{ model: target }];
		await handlers.get("session_start")({ reason: "new" }, ctx);
		assert.deepEqual(selected, ["b"], "a scoped model set must retain precedence");
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})","selector_identity":{"source_title":""new sessions apply an available project default through session-only extension activation"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

