				},
				async setModel(model) {
					selected.push(model.id);
					return true;
				},
				setThinkingLevel(level) {
					levels.push(level);
				},
			});
			const current = { provider: "p", id: "a", name: "A", contextWindow: 100_000, maxTokens: 10_000 };
