{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":81800,"end":81887,"raw_source":""last model restore stays off unless requested and warns when the model is unavailable"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""last model restore stays off unless requested and warns when the model is unavailable"","registration_line":2267,"start":81795,"end":83736,"registration_guards":[]},"title_hierarchy":[{"registration_line":2267,"call":"test","title_source":""last model restore stays off unless requested and warns when the model is unavailable""}],"guards":[],"non_ascii_source":false,"call_source":"test("last model restore stays off unless requested and warns when the model is unavailable", async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-model-picker-restore-off-"));
	try {
		const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
		const projectKey = deriveProjectKey(root);
		new ModelPickerStore(paths).recordDispatch({ provider: "p", modelId: "b" }, projectKey);

		const offIntegration = createJouzuModelPicker(paths);
		const offHandlers = new Map();
		const offSelected = [];
		offIntegration.extension.factory({
			on(name, handler) {
				offHandlers.set(name, handler);
			},
			async setModel(model) {
				offSelected.push(model.id);
				return true;
			},
			setThinkingLevel() {},
		});
		const current = { provider: "p", id: "a", name: "A", contextWindow: 100_000, maxTokens: 10_000 };
		const makeCtx = (find, notifications) => ({
			mode: "tui",
			cwd: root,
			model: current,
			scopedModels: [],
			sessionManager: { getBranch: () => [] },
			modelRegistry: { find },
			ui: { notify: (...values) => notifications?.push(values) },
		});
		await offHandlers.get("session_start")(
			{ reason: "startup" },
			makeCtx(() => undefined, []),
		);
		assert.deepEqual(offSelected, [], "restore must be opt-in so embedded hosts keep Pi's own selection");

		const onIntegration = createJouzuModelPicker(paths, { restoreLastModelAtStartup: true });
		const onHandlers = new Map();
		onIntegration.extension.factory({
			on(name, handler) {
				onHandlers.set(name, handler);
			},
			async setModel() {
				return true;
			},
			setThinkingLevel() {},
		});
		const notifications = [];
		await onHandlers.get("session_start")(
			{ reason: "startup" },
			makeCtx(() => undefined, notifications),
		);
		assert.match(notifications[0][0], /Last used model is unavailable: p\/b/);
		assert.equal(notifications[0][1], "warning");
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})","selector_identity":{"source_title":""last model restore stays off unless requested and warns when the model is unavailable"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

