{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":85368,"end":85430,"raw_source":""failed project activation does not persist a project default"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""failed project activation does not persist a project default"","registration_line":2369,"start":85363,"end":87334,"registration_guards":[]},"title_hierarchy":[{"registration_line":2369,"call":"test","title_source":""failed project activation does not persist a project default""}],"guards":[],"non_ascii_source":false,"call_source":"test("failed project activation does not persist a project default", async (testContext) => {
	for (const [name, setModel] of [
		["missing authentication", async () => false],
		["activation error", async () => Promise.reject(new Error("activation failed"))],
	]) {
		await testContext.test(name, async () => {
			const root = mkdtempSync(join(tmpdir(), "jouzu-model-picker-failed-default-"));
			try {
				const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
				const integration = createJouzuModelPicker(paths);
				const handlers = new Map();
				integration.extension.factory({
					on(event, handler) {
						handlers.set(event, handler);
					},
					setModel,
				});
				const model = { provider: "p", id: "m", name: "M", contextWindow: 100_000, maxTokens: 10_000 };
				let component;
				const ctx = {
					mode: "tui",
					cwd: root,
					model,
					scopedModels: [],
					sessionManager: { getBranch: () => [] },
					modelRegistry: {
						getAvailable: () => [model],
						refresh: async () => ({ errors: new Map() }),
						find: () => model,
					},
					getContextUsage: () => ({ tokens: 100, contextWindow: 100_000, percent: 1 }),
					isIdle: () => true,
					ui: {
						notify() {},
						custom(factory) {
							return new Promise((resolve) => {
								component = factory(
									{ terminal: { rows: 30 }, requestRender() {} },
									identityTheme,
									fakeKeybindings(),
									resolve,
								);
							});
						},
					},
				};
				await handlers.get("session_start")({ reason: "startup" }, ctx);
				const opened = integration.open({ source: "action" });
				await Promise.resolve();
				component.handleInput("enter");
				await new Promise((resolve) => setTimeout(resolve, 5));
				component.handleInput("escape");
				await opened;
				assert.deepEqual(new ModelPickerStore(paths).load().state.defaults.projects, {});
			} finally {
				rmSync(root, { recursive: true, force: true });
			}
		});
	}
})","selector_identity":{"source_title":""failed project activation does not persist a project default"","potential_instances":1,"qualifier":"Conditional registered source title; ancestor title components retained, native reporter format external."}}

