			} finally {
				rmSync(root, { recursive: true, force: true });
			}
		})"}

{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":87342,"end":87418,"raw_source":""corrupt picker state is quarantined and reported after a UI context exists"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""corrupt picker state is quarantined and reported after a UI context exists"","registration_line":2430,"start":87337,"end":88772,"registration_guards":[]},"title_hierarchy":[{"registration_line":2430,"call":"test","title_source":""corrupt picker state is quarantined and reported after a UI context exists""}],"guards":[],"non_ascii_source":false,"call_source":"test("corrupt picker state is quarantined and reported after a UI context exists", async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-model-picker-corrupt-launch-"));
	try {
		const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
		mkdirSync(paths.stateDir, { recursive: true });
		const statePath = join(paths.stateDir, "model-picker.json");
		writeFileSync(statePath, "{ broken");
		const integration = createJouzuModelPicker(paths);
		assert.equal(readFileSync(statePath, "utf8"), "{ broken", "construction must not recover without a UI");
		const handlers = new Map();
		integration.extension.factory({
			on(event, handler) {
				handlers.set(event, handler);
			},
			setModel: async () => true,
		});
		const notifications = [];
		await handlers.get("session_start")(
			{ reason: "startup" },
			{
				mode: "tui",
				cwd: root,
				model: undefined,
				scopedModels: [],
				sessionManager: { getBranch: () => [] },
				ui: { notify: (...values) => notifications.push(values) },
			},
		);
		assert.equal(existsSync(statePath), false);
		assert.equal(
			readdirSync(paths.stateDir).some((name) => name.startsWith("model-picker.corrupt-")),
			true,
		);
		assert.equal(notifications.length, 1);
		assert.match(notifications[0][0], /Unreadable model picker state was preserved/);
		assert.equal(notifications[0][1], "warning");
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
