{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":92387,"end":92455,"raw_source":""typing reuses the cached total instead of re-ranking the inventory"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""typing reuses the cached total instead of re-ranking the inventory"","registration_line":2564,"start":92382,"end":93002,"registration_guards":[]},"title_hierarchy":[{"registration_line":2564,"call":"test","title_source":""typing reuses the cached total instead of re-ranking the inventory""}],"guards":[],"non_ascii_source":false,"call_source":"test("typing reuses the cached total instead of re-ranking the inventory", () => {
