{"kind":"test-title-selector","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":93010,"end":93058,"raw_source":""toggling a favorite refreshes the cached total"","token_kind":"string","call_name":"test","argument_index":0,"test_owner":{"title_source":""toggling a favorite refreshes the cached total"","registration_line":2587,"start":93005,"end":93710,"registration_guards":[]},"title_hierarchy":[{"registration_line":2587,"call":"test","title_source":""toggling a favorite refreshes the cached total""}],"guards":[],"non_ascii_source":false,"call_source":"test("toggling a favorite refreshes the cached total", () => {
	const queries = [];
	const { component } = createComponent({
		getRows: (query) => {
			queries.push(query);
			return rows();
		},
	});

	// Type first so the active query is distinguishable from the count queries.
	component.handleInput("z");
	queries.length = 0;

	component.handleInput("\u0006");
	// A favorite moves the row in the base order, so the total is recomputed
	// and the active query is ranked once more.
	assert.equal(queries.filter((query) => query === "").length, 1, "the total refreshes once");
	assert.deepEqual(
		queries.filter((query) => query !== ""),
		["z"],
		"the active query is re-ranked exactly once",
	);
