	const { ModelRuntime, ModelRegistry } = await import("@earendil-works/pi-coding-agent");
	const root = mkdtempSync(join(tmpdir(), "jouzu-picker-gateway-"));
	try {
		const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
