			readFileSync(join(import.meta.dirname, "..", "catalog", "fixtures", "account-snapshot-v1.json"), "utf8"),
		);
		const env = { PICKER_GATEWAY_TOKEN: "picker-gateway-jwt" };
		const source = new CatalogSourceStore(paths).add({
