		writeFileSync(
			modelsPath,
			JSON.stringify({
				providers: {
					"ai.example.gateway": {
						api: "openai-completions",
						baseUrl: "https://direct.example.test/v1",
						apiKey: "$MISSING_DIRECT_KEY",
						models: [{ id: "example-model", name: "Direct model" }],
					},
				},
			}),
		);
