			modelRegistry: registry,
			sessionManager: { getBranch: () => [] },
			getContextUsage: () => undefined,
			isIdle: () => true,
			ui: {
				notify() {},
				custom: (factory) =>
					new Promise((resolve, reject) => {
						const component = factory(
							{ terminal: { rows: 30 }, requestRender() {} },
							identityTheme,
							fakeKeybindings(),
							resolve,
						);
