{"kind":"test-registration-boundary","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":53059,"end":54021,"raw_source":"test("Models view silently reranks the inventory after refresh", async () => {
	let resolveRefresh;
	let refreshed = false;
	const { component, calls } = createComponent({
		getRows: () => [
			{
				section: "other",
				model: {
					provider: "p",
					modelId: refreshed ? "fresh" : "cached",
					name: refreshed ? "Fresh" : "Cached",
					contextWindow: 100_000,
					maxTokens: 10_000,
					available: true,
				},
				contextFit: "fits",
				favorite: false,
				projectDefault: false,
				rank: 0,
			},
		],
		onRefresh: () =>
			new Promise((resolve) => {
				resolveRefresh = resolve;
			}),
	});
	assert.match(component.render(72).join("\n"), /p\/cached/);
	refreshed = true;
	resolveRefresh();
	await new Promise((resolve) => setImmediate(resolve));
	const rendered = component.render(72).join("\n");
	assert.match(rendered, /p\/fresh/);
	assert.doesNotMatch(rendered, /catalogs refreshed/i);
	assert.ok(calls.renders > 0);
	component.dispose();
})","call_name":"test","arguments":[""Models view silently reranks the inventory after refresh"","async () => {
