{"kind":"test-registration-boundary","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":54540,"end":55053,"raw_source":"test("Models view aborts an in-flight refresh when disposed", async () => {
	let refreshSignal;
	const { component } = createComponent({
		onRefresh: (signal) => {
			refreshSignal = signal;
			return new Promise((_resolve, reject) => {
				signal.addEventListener("abort", () => reject(new Error("aborted")), { once: true });
			});
		},
	});
	assert.equal(refreshSignal.aborted, false);
	component.dispose();
	await new Promise((resolve) => setImmediate(resolve));
	assert.equal(refreshSignal.aborted, true);
})","call_name":"test","arguments":[""Models view aborts an in-flight refresh when disposed"","async () => {
