{"kind":"test-registration-boundary","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":59292,"end":59909,"raw_source":"test("favorite cycling serializes repeated keypresses", async () => {
	let finishSwitch;
	const harness = await createFavoriteCycleHarness({
		favorites: ["a", "b", "c"],
		setModel: () =>
			new Promise((resolve) => {
				finishSwitch = resolve;
			}),
	});
	try {
		const first = harness.integration.cycleFavorite("forward");
		assert.equal(await harness.integration.cycleFavorite("forward"), true);
		assert.deepEqual(harness.selected, ["b"]);
		assert.match(harness.notifications[0][0], /already in progress/);
		finishSwitch(true);
		assert.equal(await first, true);
	} finally {
		await harness.dispose();
	}
})","call_name":"test","arguments":[""favorite cycling serializes repeated keypresses"","async () => {
