{"kind":"test-registration-boundary","path":"packages/cli/test/model-picker.test.mjs","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","start":65137,"end":67100,"raw_source":"test("Enter selects a model and stores it for the project", async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-model-picker-persist-selection-"));
	try {
		const paths = resolveJouzuPaths({ homeOverride: join(root, "home") });
		const integration = createJouzuModelPicker(paths);
		const handlers = new Map();
		const selected = [];
		let ctx;
		integration.extension.factory({
			on(name, handler) {
				handlers.set(name, handler);
			},
			async setModel(model) {
				selected.push(model.id);
				ctx.model = model;
				return true;
			},
		});
		const models = ["a", "b"].map((id) => ({
			provider: "p",
			id,
			name: id.toUpperCase(),
			contextWindow: 100_000,
			maxTokens: 10_000,
		}));
		ctx = {
			mode: "tui",
			cwd: root,
			model: models[0],
			scopedModels: [],
			sessionManager: { getBranch: () => [] },
			modelRegistry: {
				getAvailable: () => models,
				find: (provider, id) => (provider === "p" ? models.find((model) => model.id === id) : undefined),
				refresh: async () => ({ errors: new Map() }),
			},
			getContextUsage: () => ({ tokens: 100, contextWindow: 100_000, percent: 1 }),
			isIdle: () => true,
			ui: {
				notify() {},
				custom(factory) {
					return new Promise((resolve) => {
						const component = factory(
							{ terminal: { rows: 30 }, requestRender() {} },
							identityTheme,
							fakeKeybindings(),
							resolve,
						);
						setImmediate(() => {
							component.handleInput("down");
							component.handleInput("down");
							component.handleInput("enter");
						});
					});
				},
			},
		};
		await handlers.get("session_start")({ reason: "startup" }, ctx);
		assert.equal(await integration.open({ source: "action" }), true);
		assert.deepEqual(selected, ["b"]);
		assert.deepEqual(new ModelPickerStore(paths).load().state.defaults.projects[deriveProjectKey(root)], {
			provider: "p",
			modelId: "b",
		});
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})","call_name":"test","arguments":[""Enter selects a model and stores it for the project"","async () => {
